CREATE OR REPLACE FUNCTION salary_for(p_last_name IN VARCHAR2) RETURN NUMBER IS
  l_salary employees.salary%TYPE;
BEGIN
  SELECT salary INTO l_salary FROM employees WHERE last_name = p_last_name;
  RETURN l_salary;
EXCEPTION
  WHEN TOO_MANY_ROWS THEN
    RAISE_APPLICATION_ERROR(
      -20001,
      'salary_for: more than one employee has last_name=' || p_last_name
    );
END salary_for;

CREATE OR REPLACE FUNCTION display_name(p_employee_id IN NUMBER) RETURN VARCHAR2 IS
  l_name VARCHAR2(46);
BEGIN
  SELECT first_name || ' ' || last_name INTO l_name
    FROM employees WHERE employee_id = p_employee_id;
  RETURN l_name;
END display_name;

CREATE OR REPLACE PROCEDURE close_department(p_department_id IN NUMBER) IS
BEGIN
  UPDATE employees SET status = 'INACTIVE' WHERE department_id = p_department_id;
  DELETE FROM departments WHERE department_id = p_department_id;
END close_department;

CREATE OR REPLACE FUNCTION manager_name(p_department_id IN NUMBER) RETURN VARCHAR2 IS
  l_name employees.last_name%TYPE;
BEGIN
  SELECT e.last_name INTO l_name
    FROM departments d JOIN employees e ON e.employee_id = d.manager_id
   WHERE d.department_id = p_department_id;
  RETURN l_name;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    RETURN NULL;
END manager_name;

CREATE OR REPLACE PROCEDURE HARNESS_APP.ARCHIVE_OLD_ORDERS(
  p_before_date IN DATE
) AS
  TYPE t_rows IS TABLE OF HARNESS_APP.ORDERS%ROWTYPE;
  l_rows t_rows;

  CURSOR c_old_orders IS
    SELECT ORDER_ID,
           CUSTOMER_ID,
           ORDER_DATE,
           STATUS,
           TOTAL
      FROM HARNESS_APP.ORDERS
     WHERE ORDER_DATE < p_before_date;
BEGIN
  OPEN c_old_orders;

  LOOP
    FETCH c_old_orders BULK COLLECT INTO l_rows LIMIT 10000;

    EXIT WHEN l_rows.COUNT = 0;

    FORALL i IN 1 .. l_rows.COUNT
      INSERT INTO HARNESS_APP.ORDERS_ARCHIVE (
        ORDER_ID,
        CUSTOMER_ID,
        ORDER_DATE,
        STATUS,
        TOTAL
      ) VALUES (
        l_rows(i).ORDER_ID,
        l_rows(i).CUSTOMER_ID,
        l_rows(i).ORDER_DATE,
        l_rows(i).STATUS,
        l_rows(i).TOTAL
      );

    FORALL i IN 1 .. l_rows.COUNT
      DELETE FROM HARNESS_APP.ORDERS
       WHERE ORDER_ID = l_rows(i).ORDER_ID;
  END LOOP;

  CLOSE c_old_orders;
END ARCHIVE_OLD_ORDERS;
